git log --oneline | head -3 && cat >> src/board.test.ts <<'EOF'

import { createBoard, type Board, type ColumnConfig } from "./board";

function setup(columns: ColumnConfig[] = [{ name: "Backlog" }, { name: "Doing" }, { name: "Review" }, { name: "Done" }]) {
  const clock = { t: 0 };
  const board: Board = createBoard({ columns, now: () => clock.t });
  return { board, clock };
}

test("addCard returns C1 and lists the card in the first column", () => {
  const { board } = setup();
  expect(board.addCard("Fix login")).toBe("C1");
  expect(board.cardsIn("Backlog")).toEqual(["C1"]);
});
EOF
.claude/skills/tdd-deep-modules/scripts/tdd-step red "addCard returns C1 in first column" 2>&1 | tail -15

S=.claude/skills/tdd-deep-modules/scripts; $S/tdd-step green "ids count up" 2>&1 | tail -5
cat >> src/board.test.ts <<'EOF'

function codeOf(action: () => unknown): string | undefined {
  try {
    action();
  } catch (error) {
    if (error instanceof BoardError) return error.code;
    throw error;
  }
  return undefined;
}

test("addCard rejects a blank title with EMPTY_TITLE without consuming an id", () => {
  const { board } = setup();
  expect(codeOf(() => board.addCard("   "))).toBe("EMPTY_TITLE");
  expect(board.cardsIn("Backlog")).toEqual([]);
  expect(board.addCard("real")).toBe("C1");
});
EOF
$S/tdd-step red "addCard rejects blank title" 2>&1 | tail -5

cat >> src/board.test.ts <<'EOF'

test("addCard rejects with WIP_LIMIT when the first column is full", () => {
  const { board } = setup([{ name: "Backlog", wipLimit: 2 }, { name: "Done" }]);
  board.addCard("a");
  board.addCard("b");
  expect(codeOf(() => board.addCard("c"))).toBe("WIP_LIMIT");
  expect(board.cardsIn("Backlog")).toEqual(["C1", "C2"]);
});
EOF
